suppressMessages(library(dplyr));setwd("/Users/hanno/Documents/GitHub/german_election_data")
fu<-readRDS("data/federal_elections/municipality_level/final/federal_muni_unharm.rds")
fc<-readRDS("data/federal_elections/county_level/final/federal_cty_unharm.rds")
m<-fu%>%group_by(state,election_year)%>%summarise(nv=sum(number_voters,na.rm=T),vv=sum(valid_votes,na.rm=T),ev0=sum(eligible_voters_orig,na.rm=T),n=n(),.groups="drop")
c<-fc%>%group_by(state,election_year=year)%>%summarise(cnv=sum(number_voters,na.rm=T),cvv=sum(valid_votes,na.rm=T),cev=sum(eligible_voters,na.rm=T),ncty=n(),nbw=sum(grepl("999$",ags)),.groups="drop")
x<-full_join(m,c,by=c("state","election_year"))%>%mutate(dnv=nv/cnv-1,dvv=vv/cvv-1,dev=ev0/cev-1)
x<-x%>%filter(election_year>=1980);print(as.data.frame(x%>%filter(abs(dnv)>.002|abs(dvv)>.002|abs(dev)>.002)%>%select(state,election_year,nv,cnv,dnv,dvv,dev)),digits=3)
cat("national: ");print(as.data.frame(x%>%group_by(election_year)%>%summarise(nv=sum(nv),cnv=sum(cnv),d=sum(nv)/sum(cnv)-1)%>%filter(abs(d)>.001)))
# county-level (5-digit) ags compare
fu$cty<-substr(fu$ags,1,5)
mm<-fu%>%group_by(ags=cty,year=election_year)%>%summarise(nv=sum(number_voters,na.rm=T),ev=sum(eligible_voters_orig,na.rm=T),.groups="drop")
jj<-inner_join(mm,fc%>%select(ags,year,cnv=number_voters,cev=eligible_voters),by=c("ags","year"))
cat("county rows matched",nrow(jj)," of cty rows",nrow(fc),"; muni counties not in cty:",nrow(anti_join(mm,fc,by=c("ags","year"))),"\n")
print(as.data.frame(jj%>%filter(year>=1990,abs(ev/cev-1)>.01|abs(nv/cnv-1)>.01)%>%mutate(rn=nv/cnv,re=ev/cev)%>%count(year)),row.names=F)
print(head(as.data.frame(anti_join(mm,fc,by=c("ags","year"))%>%filter(year>=2002)),10))
